SELECT u.user_id, u.user_name, u.credit - IFNULL(outflow.total_out, 0) + IFNULL(inflow.total_in, 0) AS credit, CASE WHEN u.credit - IFNULL(outflow.total_out, 0) + IFNULL(inflow.total_in, 0) < 0 THEN 'Yes' ELSE 'No' END AS credit_limit_breached FROM Users u LEFT JOIN (SELECT paid_by, SUM(amount) AS total_out FROM Transactions GROUP BY paid_by) outflow ON u.user_id = outflow.paid_by LEFT JOIN (SELECT paid_to, SUM(amount) AS total_in FROM Transactions GROUP BY paid_to) inflow ON u.user_id = inflow.paid_to;
